package fr.etudeplus.app;
import android.app.Activity;
import android.os.Bundle;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.speech.tts.TextToSpeech;
import android.view.*;
import android.widget.*;
import java.util.Locale;
public class MainActivity extends Activity {
 private final String[] levels={"Primaire","Collège","Lycée","Avancé","Expert"}, subjects={"Français","Mathématiques","Sciences"};
 private static final String[][][][] QUESTIONS = {{{{"Quel mot désigne un animal ?","Chat","Table","Chat","Le chat est un être vivant."},{"Complète : Les oiseaux ...","volent","vole","volent","Le sujet est au pluriel."},{"Quel mot est un verbe ?","Courir","Bleu","Courir","Un verbe exprime une action ou un état."},{"Quel mot rime avec maison ?","Saison","Soleil","Saison","Maison et saison se terminent par le même son."}},{{"Combien font 8 + 7 ?","15","14","15","8 + 7 = 15."},{"Combien font 6 × 4 ?","24","28","24","6 groupes de 4 font 24."},{"Combien vaut la moitié de 38 ?","19","16","19","38 divisé par 2 vaut 19."},{"Combien font 50 − 17 ?","33","37","33","50 − 17 = 33."}},{{"Quel organe permet de respirer ?","Poumons","Estomac","Poumons","Les poumons assurent les échanges gazeux."},{"Quel état a l'eau à −5 °C ?","Solide","Gazeux","Solide","L'eau pure gèle vers 0 °C."},{"De quoi une plante a-t-elle besoin pour la photosynthèse ?","Lumière","Plastique","Lumière","La lumière fournit l'énergie nécessaire."},{"Quelle planète est la plus proche du Soleil ?","Mercure","Mars","Mercure","Mercure est la planète la plus proche du Soleil."}}},{{{"Dans « Je parle à Léa », « à Léa » est...","COI","COD","COI","Le groupe complète le verbe avec la préposition à."},{"Quel temps : « nous avions terminé » ?","Plus-que-parfait","Passé simple","Plus-que-parfait","Auxiliaire à l'imparfait et participe passé."},{"Quelle figure : « le vent murmure » ?","Personnification","Comparaison","Personnification","Le vent reçoit une action humaine."},{"Quel mot est un adverbe ?","Rapidement","Rapide","Rapidement","Rapidement modifie un verbe, un adjectif ou un autre adverbe."}},{{"Combien vaut 3/4 + 1/8 ?","7/8","4/12","7/8","3/4 = 6/8, puis 6/8 + 1/8 = 7/8."},{"Résous 3x + 5 = 20.","x = 5","x = 7","x = 5","3x = 15, donc x = 5."},{"Triangle rectangle : côtés 6 et 8. Hypoténuse ?","10","14","10","Par Pythagore : racine de 36 + 64 = 10."},{"Combien font 15 % de 240 ?","36","24","36","0,15 × 240 = 36."}},{{"Un atome neutre a 8 protons. Combien d'électrons ?","8","16","8","Un atome neutre possède autant de protons que d'électrons."},{"Quel est le pH d'une solution acide ?","Inférieur à 7","Supérieur à 7","Inférieur à 7","Une solution acide a un pH inférieur à 7."},{"Quel organe produit la bile ?","Foie","Pancréas","Foie","Le foie produit la bile, stockée dans la vésicule biliaire."},{"Dans un circuit en série, si une lampe grille...","Toutes s'éteignent","Les autres brillent plus","Toutes s'éteignent","Le circuit est ouvert."}}},{{{"« Il eût fallu » : quel mode et temps ?","Conditionnel passé 2e forme","Subjonctif présent","Conditionnel passé 2e forme","Il s'agit de la forme littéraire du conditionnel passé, identique au plus-que-parfait du subjonctif."},{"Quel courant privilégie la raison et la critique au XVIIIe siècle ?","Lumières","Surréalisme","Lumières","Les Lumières valorisent l'esprit critique et la raison."},{"« Cette obscure clarté » est...","Oxymore","Anaphore","Oxymore","Deux termes contradictoires sont rapprochés."},{"Un narrateur omniscient connaît...","Les pensées de tous","Uniquement ses pensées","Les pensées de tous","Il a accès aux pensées et aux événements hors du champ d'un personnage."}},{{"Dérivée de f(x)=3x²−4x+1 ?","6x−4","3x−4","6x−4","La dérivée de 3x² est 6x."},{"Résous x²−5x+6=0.","2 et 3","−2 et −3","2 et 3","(x−2)(x−3)=0."},{"Combien vaut log10(1000) ?","3","10","3","10 puissance 3 vaut 1000."},{"Probabilité de 2 piles en 2 lancers équitables ?","1/4","1/2","1/4","Les quatre issues sont équiprobables."}},{{"Quelle unité mesure la résistance électrique ?","Ohm","Watt","Ohm","La résistance électrique se mesure en ohms."},{"À 25 °C, quel pH est neutre ?","7","0","7","Pour l'eau à 25 °C, le pH neutre vaut 7."},{"Une mole contient environ...","6,02 × 10²³ entités","6,02 × 10⁶ entités","6,02 × 10²³ entités","C'est la constante d'Avogadro."},{"L'ADN est transcrit en...","ARN","Protéine directement","ARN","La transcription produit une molécule d'ARN."}}},{{{"Un argument valide est-il forcément vrai dans ses prémisses ?","Non","Oui","Non","La validité concerne la structure de l'inférence, pas la vérité des prémisses."},{"Dans « Si P alors Q », la contraposée est...","Si non Q alors non P","Si Q alors P","Si non Q alors non P","La contraposée est logiquement équivalente à l'implication."},{"Une antithèse oppose...","Deux idées","Deux syllabes","Deux idées","L'antithèse rapproche des idées opposées."},{"Quel biais consiste à privilégier les informations qui nous confortent ?","Confirmation","Disponibilité seulement","Confirmation","Le biais de confirmation favorise les éléments compatibles avec nos croyances."}},{{"Limite de sin(x)/x quand x tend vers 0 ?","1","0","1","Limite fondamentale en radians."},{"Intégrale de 0 à 1 de 3x² dx ?","1","3","1","Primitive x³ ; entre 0 et 1, le résultat vaut 1."},{"Combien de sous-ensembles pour un ensemble de 6 éléments ?","64","36","64","Un ensemble de n éléments a 2 puissance n sous-ensembles."},{"Une matrice 2×2 de déterminant nul est...","Non inversible","Orthogonale","Non inversible","Une matrice carrée est inversible si son déterminant est non nul."}},{{"Quel principe lie symétrie temporelle et conservation de l'énergie ?","Théorème de Noether","Principe de Pascal","Théorème de Noether","La symétrie par translation dans le temps implique une quantité conservée."},{"L'entropie d'un système isolé évolue spontanément comment ?","Elle ne diminue pas","Elle diminue toujours","Elle ne diminue pas","Deuxième principe de la thermodynamique."},{"Une mutation silencieuse change-t-elle nécessairement la protéine ?","Non","Oui","Non","La dégénérescence du code génétique peut préserver l'acide aminé."},{"Quel phénomène explique le décalage vers le rouge cosmologique ?","Expansion de l'Univers","Rotation de la Terre","Expansion de l'Univers","L'expansion étire les longueurs d'onde de la lumière."}}}};
 private LinearLayout root; private TextToSpeech speech; private int level=0,subject=0,index=0,correct=0,attempts=0;
 private final int ink=Color.rgb(35,55,69), accent=Color.rgb(28,115,105);
 @Override public void onCreate(Bundle state){super.onCreate(state);speech=new TextToSpeech(this,status->{if(status==TextToSpeech.SUCCESS)speech.setLanguage(Locale.FRENCH);});home();}
 private GradientDrawable shape(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(26);return d;}
 private TextView label(String value,int size,boolean bold){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(ink);t.setPadding(16,14,16,14);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
 private void page(String title){ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(22,24,22,30);root.setBackgroundColor(Color.rgb(250,248,241));scroll.addView(root);setContentView(scroll);root.addView(label("🌱 Étude+",28,true));root.addView(label(title,23,true));}
 private void button(String name,Runnable click){TextView t=label(name,20,true);t.setTextColor(Color.WHITE);t.setGravity(Gravity.CENTER);t.setMinHeight(68);t.setBackground(shape(accent));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,8,0,8);root.addView(t,p);t.setOnClickListener(v->click.run());}
 private void speak(String s){if(speech!=null)speech.speak(s,TextToSpeech.QUEUE_FLUSH,null,"etude");}
 private void home(){page("Choisis ta difficulté");root.addView(label("Cinq niveaux progressifs. Change de niveau librement, sans limite de temps.",18,false));for(int i=0;i<levels.length;i++){final int n=i;button(levels[i],()->{level=n;chooseSubject();});}}
 private void chooseSubject(){page("Niveau : "+levels[level]);for(int i=0;i<subjects.length;i++){final int n=i;button(subjects[i],()->{subject=n;index=0;correct=0;attempts=0;exercise();});}button("← Changer de niveau",this::home);}
 private void exercise(){page(levels[level]+" · "+subjects[subject]);String[] item=QUESTIONS[level][subject][index];root.addView(label("Question "+(index+1)+" / "+QUESTIONS[level][subject].length,18,false));root.addView(label(item[0],23,true));button("🔊 Écouter la question",()->speak(item[0]));root.addView(label("Touche une réponse ou maintiens-la pour la glisser.",17,false));
 TextView zone=label("Dépose ta réponse ici",19,true);zone.setMinHeight(95);zone.setGravity(Gravity.CENTER);zone.setBackground(shape(Color.rgb(221,238,232)));root.addView(zone);
 final boolean[] answered={false};java.util.function.Consumer<String> verify=answer->{if(answered[0])return;attempts++;if(answer.equals(item[3])){answered[0]=true;correct++;zone.setText("✓ Bonne réponse !\n"+item[4]);zone.announceForAccessibility("Bonne réponse. "+item[4]);speak("Bravo. "+item[4]);button(index==QUESTIONS[level][subject].length-1?"Voir le bilan →":"Question suivante →",()->{index++;if(index==QUESTIONS[level][subject].length)result();else exercise();});}else{zone.setText("Essaie encore. Indice : "+item[4]);speak("Essaie encore.");}};
 for(int i=1;i<=2;i++){String answer=item[i];TextView option=label(answer,21,true);option.setMinHeight(72);option.setGravity(Gravity.CENTER);option.setBackground(shape(Color.WHITE));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,9,0,9);root.addView(option,p);option.setOnClickListener(v->verify.accept(answer));option.setOnLongClickListener(v->{ClipData clip=ClipData.newPlainText("réponse",answer);v.startDragAndDrop(clip,new View.DragShadowBuilder(v),null,0);return true;});}
 zone.setOnDragListener((v,event)->{if(event.getAction()==DragEvent.ACTION_DROP&&event.getClipData()!=null){verify.accept(event.getClipData().getItemAt(0).getText().toString());}return true;});button("← Choisir une matière",this::chooseSubject);
 }
 private void result(){int total=QUESTIONS[level][subject].length;String key="best_"+level+"_"+subject;int best=getPreferences(0).getInt(key,0);getPreferences(0).edit().putInt(key,Math.max(best,correct)).apply();page("Bilan : "+levels[level]);root.addView(label("Questions réussies : "+correct+" / "+total,23,true));root.addView(label("Tentatives : "+attempts+". Tu peux recommencer sans pénalité.",18,false));button("Recommencer",()->{index=0;correct=0;attempts=0;exercise();});if(level<levels.length-1)button("Passer au niveau "+levels[level+1],()->{level++;chooseSubject();});button("Autre matière",this::chooseSubject);button("Accueil",this::home);}
 @Override protected void onDestroy(){if(speech!=null){speech.stop();speech.shutdown();}super.onDestroy();}
}